SELECT "TableroSistemaPenal_6"."AUDIENCIA" AS "AUDIENCIA",   SUM(CAST("TableroSistemaPenal_6"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok",   CAST(EXTRACT(YEAR FROM "TableroSistemaPenal_6"."FECHA_AUDIENCIA") AS BIGINT) AS "yr_FECHA_AUDIENCIA_ok" FROM "TableroSistemaPenal_6" WHERE (("TableroSistemaPenal_6"."AUDIENCIA" IN ('AUDIENCIA DE JUICIO ORAL TOP', 'AUDIENCIA DE LECTURA DE SENTENCIA.')) AND ("TableroSistemaPenal_6"."TIP_TRIB" = 'Oral')) GROUP BY "TableroSistemaPenal_6"."AUDIENCIA",   "yr_FECHA_AUDIENCIA_ok";
